<?php
require_once __DIR__.'/requirement_document_common.php';$user=rdUser();
try{if($_SERVER['REQUEST_METHOD']!=='POST')rdResponse(['success'=>false,'error'=>'Methode nicht erlaubt.'],405);$d=rdBody();$id=trim((string)($d['id']??''));$blocks=$d['blocks']??null;if($id===''||!is_array($blocks))rdResponse(['success'=>false,'error'=>'Dokument-ID und Blöcke fehlen.'],422);
$pdo->beginTransaction();rdDocument($pdo,$id,true);$title=trim((string)($d['title']??''));if($title==='')throw new RuntimeException('Titel fehlt.');$status=rdAllowed(trim((string)($d['status']??'Open')),['Open','In Progress','Reviewed','Closed'],'Open');$priority=rdAllowed(trim((string)($d['priority']??'Medium')),['Low','Medium','High','Critical'],'Medium');$relevance=rdAllowed(trim((string)($d['relevance']??'Must')),['Must','Should','Could','Won\'t'],'Must');$review=rdAllowed(trim((string)($d['review_status']??'New')),['New','In Review','Approved','Rejected'],'New');
$pdo->prepare('UPDATE requirement_documents SET title=?,status=?,priority=?,relevance=?,review_status=?,metadata=?,updated_by=? WHERE id=?')->execute([$title,$status,$priority,$relevance,$review,json_encode($d['metadata']??[],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),$user,$id]);
$o=$pdo->prepare('SELECT id FROM requirement_document_blocks WHERE document_id=?');$o->execute([$id]);$known=array_fill_keys($o->fetchAll(PDO::FETCH_COLUMN),true);$keep=[];$ins=$pdo->prepare('INSERT INTO requirement_document_blocks(id,document_id,editor_block_id,block_type,content,sort_order)VALUES(?,?,?,?,?,?)');$upd=$pdo->prepare('UPDATE requirement_document_blocks SET editor_block_id=?,block_type=?,content=?,sort_order=? WHERE id=? AND document_id=?');foreach(array_values($blocks)as$i=>$b){if(!is_array($b))continue;$data=is_array($b['data']??null)?$b['data']:[];$rid=trim((string)($data['_recordId']??''));unset($data['_recordId']);if(($b['type']??'')==='heading'){$data['level']=max(3,min(5,(int)($data['level']??3)));}$json=json_encode($data,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);$eid=trim((string)($b['id']??''));$type=trim((string)($b['type']??'text'));if(isset($known[$rid])){$upd->execute([$eid?:null,$type,$json,$i,$rid,$id]);$keep[]=$rid;}else{$rid=rdUuid();$ins->execute([$rid,$id,$eid?:null,$type,$json,$i]);$keep[]=$rid;}}
